-- Полное соответствие истории field реестру событий; исходная формула hashdiff применяется к сохранённому тексту payload.
WITH expected AS (SELECT lower(to_hex(md5(to_utf8('field:' || entity_id)))) AS field_hk,event_id,entity_version,op,event_time,lower(to_hex(md5(to_utf8(op || ':' || payload)))) AS hashdiff,json_extract_scalar(payload,'$.field_name') AS field_name,json_extract_scalar(payload,'$.region') AS region FROM {{target:oil_dds__event}} WHERE event_type='field'), actual AS (SELECT field_hk,event_id,entity_version,op,event_time,hashdiff,field_name,region FROM {{target:oil_dds__sat_field}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
